def solve(gi, fill1_full=False):
    H,W=len(gi),len(gi[0]); bg=gi[0][0]
    pts=[(i,j,v) for i,row in enumerate(gi) for j,v in enumerate(row) if v!=bg]
    ones=[p for p in pts if p[2]==1]; sixes=[p for p in pts if p[2]==6]
    res=[row[:] for row in gi]
    pair=None
    for a in ones:
        for b in ones:
            if a>=b: continue
            da=a[0]-b[0]; db=a[1]-b[1]
            if abs(da)==abs(db): pair=(a,b); break
        if pair: break
