            nxt=(cur[0]-dr,cur[1]-dc)
            if not(0<=nxt[0]<H and 0<=nxt[1]<W) or res[nxt[0]][nxt[1]]!=bg: break
            res[nxt[0]][nxt[1]]=1; cur=nxt
